import{renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import{buildInfection}from './infection-meshes.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function infectionFigure(w={}){let{kind='types',state='bacterium',revealed=true}=w;let title=w.title||'Explore the mechanism',status=revealed?(w.result||'Symbolic comparison'):'Baseline · predict before revealing';let picture='',labels=[];const text=(x,y,t)=>{let lines=[],line='';for(let word of t.split(' ')){if((line+' '+word).trim().length>32&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);return `<text x="${x}" y="${y}" text-anchor="middle" fill="#f5eee5" font-size="24">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?27:0}">${esc(l)}</tspan>`).join('')}</text>`;};
if(['replicate','host','virus','damage','phagocyte'].includes(kind)){let outside=kind==='phagocyte'?state==='approach':state==='entry',digest=state==='digest'&&revealed,n=revealed&&['copies','release'].includes(state)?7:1;picture='<ellipse cx="265" cy="205" rx="145" ry="110" fill="#7fa1a1" fill-opacity=".35" stroke="#bdd3ce" stroke-width="4"/><ellipse cx="205" cy="240" rx="28" ry="22" fill="#b0a0b5"/>';for(let i=0;i<n;i++){let x=outside?460:270+Math.sin(i*2)*70,y=outside?160:200+Math.cos(i*2)*55;picture+=`<${digest?'rect':'circle'} ${digest?`x="${x}" y="${y}" width="14" height="14"`:`cx="${x}" cy="${y}" r="${n===1?18:12}"`} fill="#efb298" stroke="#f7d7b7" stroke-width="3"/>`;}labels=[[265,75,kind==='phagocyte'?'White cell cutaway':'Host cell cutaway'],[280,355,outside?'Pathogen outside':digest?'Digested fragments':'Pathogen material inside']];}
else if(kind==='leaf'){picture=state==='dropped'&&revealed?'<path d="M280 290V110" stroke="#c8d3b2" stroke-width="6"/>':'<path d="M280 310Q70 150 280 65Q490 150 280 310" fill="#95b6a0" stroke="#d9dec2" stroke-width="3"/><path d="M280 310V75" stroke="#e5d7ad" stroke-width="3"/>';if(revealed&&['tmv','blackspot'].includes(state))for(let i=0;i<9;i++)picture+=`<circle cx="${230+(i%3)*50}" cy="${140+Math.floor(i/3)*45}" r="${state==='tmv'?18:12}" fill="${state==='tmv'?'#dfcd96':'#675768'}"/>`;labels=[[280,345,state==='dropped'?'Less remaining leaf area':state==='tmv'?'Mosaic damage':state==='blackspot'?'Fungal spots / yellowing':'Intact comparison']];}
else if(kind==='mosquito'){picture='<ellipse cx="280" cy="200" rx="18" ry="55" fill="#cbb39f"/><ellipse cx="225" cy="160" rx="65" ry="22" fill="#b4c9ce" transform="rotate(25 225 160)"/><ellipse cx="335" cy="160" rx="65" ry="22" fill="#b4c9ce" transform="rotate(-25 335 160)"/><circle cx="280" cy="130" r="18" fill="#d4c1aa"/><path d="M280 115V80M265 185L180 220M295 185L380 220M265 210L190 280M295 210L370 280" stroke="#e5d6bd" stroke-width="3"/>';labels=[[280,45,'Mosquito · vector'],[280,330,'Protist carried between hosts']];if(revealed&&state==='net')picture+='<path d="M160 70V300M200 70V300M240 70V300M280 70V300M320 70V300M360 70V300M400 70V300M160 100H400M160 150H400M160 200H400M160 250H400" stroke="#eee2c5" stroke-width="2"/>';}
else if(kind==='cilia'){picture='<path d="M60 245H500" stroke="#accac5" stroke-width="45"/>';for(let i=0;i<12;i++)picture+=`<path d="M${75+i*35} 225l${state==='cleared'&&revealed?15:0} -50" stroke="#eddbc0" stroke-width="3"/><circle cx="${80+i*33}" cy="155" r="7" fill="#e8a491"/>`;picture+='<path d="M130 100H430l-20 -12m20 12l-20 12" stroke="#f3c49f" stroke-width="4" fill="none"/>';labels=[[280,70,'Towards throat →'],[280,320,'Cilia move mucus with trapped particles']];}
else if(kind==='antibody'){picture='<circle cx="375" cy="180" r="65" fill="#90b3b3"/><path d="M200 290V220L160 175M200 220L240 175" stroke="#efa892" stroke-width="13" fill="none"/>';picture+=state==='wrong'?'<circle cx="240" cy="175" r="13" fill="#f0ce9e"/>':'<rect x="230" y="165" width="20" height="20" fill="#f0ce9e"/>';if(revealed&&state!=='wrong')picture=picture.replace('M200 290V220L160 175M200 220L240 175','M270 290V220L230 175M270 220L310 175');picture+='<rect x="300" y="170" width="20" height="20" fill="#f0ce9e"/>';if(revealed&&state!=='wrong')picture+='<path d="M255 180H290" stroke="#f7dfb9" stroke-width="3"/>';labels=[[200,330,state==='toxin'?'Antitoxin':'Antibody'],[375,75,state==='toxin'?'Toxin target':'Particular antigen']];}
else if(kind==='barrier'){if(state==='stomach'){picture='<path d="M210 70v80q-90 15-70 95q30 100 160 65q100-30 80-125q-10-50-55-55V70" fill="#b9958a" stroke="#edd6bd" stroke-width="5"/><path d="M160 240q100 55 200-10" stroke="#ebd2a2" stroke-width="30" fill="none"/>';labels=[[280,355,'Hydrochloric acid · kills many pathogens']];}else{picture='<path d="M80 240H480" stroke="#95b3ab" stroke-width="55"/>';if(state==='nose'){for(let i=0;i<11;i++)picture+=`<path d="M${95+i*35} 220l15-65" stroke="#e1c6a2" stroke-width="3"/>`;picture+='<path d="M80 145H480" stroke="#b5d0bd" stroke-width="14"/>';labels=[[280,330,'Hairs + mucus · trap incoming pathogens']];}else{picture+='<path d="M240 215H320" stroke="#a8796b" stroke-width="16"/>';labels=[[280,330,'Skin barrier · scab seals damage']];}for(let i=0;i<5;i++)picture+=`<circle cx="${140+i*70}" cy="110" r="9" fill="#e9ad97"/>`;}}
else if(kind==='susceptibility'){let n=revealed&&state==='susceptible'?0:6;picture='<rect x="85" y="105" width="390" height="190" rx="20" fill="none" stroke="#b5c9c8" stroke-width="3"/>';for(let i=0;i<n;i++)picture+=`<rect x="${130+(i%3)*110}" y="${145+Math.floor(i/3)*80}" width="65" height="28" rx="14" fill="#9fc7bc"/>`;labels=[[280,70,'Same antibiotic challenge'],[280,345,!revealed?'Before comparison':state==='susceptible'?'Susceptible bacteria reduced':'Resistant bacteria survive']];}
else if(kind==='types'){if(state==='fungus')picture='<path d="M280 310V170M280 220L180 150V100M280 180L360 120V80M280 265L380 210" stroke="#dfc3a2" stroke-width="13" fill="none"/>';else if(state==='virus')picture='<circle cx="280" cy="190" r="70" fill="#d6978b" stroke="#f0c89f" stroke-width="10"/>'+Array.from({length:12},(_,i)=>{let a=i*Math.PI/6;return `<path d="M${280+Math.cos(a)*70} ${190+Math.sin(a)*70}L${280+Math.cos(a)*95} ${190+Math.sin(a)*95}" stroke="#f0c89f" stroke-width="7"/>`;}).join('');else picture=`<rect x="160" y="135" width="240" height="115" rx="57" fill="#8cbbbb" stroke="#ccdbcd" stroke-width="4"/><path d="M210 190q35 -40 70 0t55 0" fill="none" stroke="#f4d5aa" stroke-width="4"/>`;labels=[[280,330,state==='bacterium'?'Bacterial cell · cellular':state==='protist'?'Protist · single cell':state==='fungus'?'Fungal hyphae':'Virus · needs living host cell']];}
else{let blocked=revealed&&['water','air','contact','barrier','measles','hiv','hygiene','skin','nose','stomach','susceptible'].includes(state);picture='<circle cx="125" cy="190" r="50" fill="#8fafb2"/><circle cx="435" cy="190" r="50" fill="#d0b09c"/><path d="M190 190H370l-20 -15m20 15l-20 15" stroke="#f1c5a4" stroke-width="5" fill="none"/>';if(blocked)picture+='<path d="M280 120V260" stroke="#eaa490" stroke-width="12"/>';labels=[[125,285,kind==='susceptibility'?'Bacteria':'Source'],[435,285,kind==='susceptibility'?'After challenge':'Recipient'],[280,80,blocked?'Selected intervention acts here':'Transfer / comparison route']];}
return `<svg class="infection-diagram" viewBox="0 0 560 410" role="img" aria-label="${esc(title+'. '+status)}">${picture}${labels.map(x=>text(...x)).join('')}</svg><p class="diagram-caption">${esc(status)}</p>`;}
export function showInfection(scene,w={}){let aliases={bacterium:['types','bacterium'],virus:['replicate','copies'],host:['host','copies'],route:['route','contact'],leaf:['leaf','tmv'],mosquito:['mosquito','vector'],barrier:['barrier','skin'],cilia:['cilia','cleared'],phagocyte:['phagocyte','engulf'],antibody:['antibody','match']};let a=aliases[scene]||[scene,'bacterium'];let options={kind:a[0],state:a[1],revealed:true,...w};let name=w.title||({types:'Small organisms, different mechanisms',replicate:'Viruses use living cells',host:'A host cell under attack',route:'Find the transmission link',leaf:'Damage changes useful leaf area',mosquito:'A carrier and a pathogen',barrier:'Reduce entry and survival',cilia:'Trap, then clear',phagocyte:'Engulf, then digest',antibody:'A specific match'}[options.kind]||'Compare the mechanism');renderCustomModel({name,formula:w.stateLabel||'Inspect the model; switch to the labelled diagram',kicker:'SCHEMATIC BIOLOGY MODEL',aria:name+'. Symbolic scale; labelled diagram available.',atoms:[],bonds:[],radius:2.5,viewKey:'infection-'+options.kind,startPaused:true,note:'Symbolic colours, sizes and stages · not diagnostic',diagram:infectionFigure({...options,title:name}),build:(g,T)=>buildInfection(g,T,options)});}
